mapper.select:
SELECT 
FROM sys_user_identity i
WHERE i.user_id = #{userId}

    AND i.identity_type = #{identityType}

ORDER BY i.create_time ASC, i.id ASC

SELECT ,
       u.nick_name, u.user_name, d.dept_name
FROM sys_user_identity i
INNER JOIN sys_user u ON u.user_id = i.user_id
LEFT JOIN sys_dept d ON d.dept_id = u.dept_id
WHERE 1 = 1

    AND i.identity_type = #{identityType}


    AND i.user_id = #{userId}

${params.dataScope}
ORDER BY u.user_id ASC, i.id ASC

mapper.insert:
INSERT INTO sys_user_identity (
    user_id, identity_type, identifier, display_name, origin, create_by, create_time
) VALUES (
    #{userId}, #{identityType}, #{identifier}, #{displayName}, #{origin},
    #{createBy}, SYSDATE()
)

mapper.delete:
DELETE FROM sys_user_identity
WHERE identity_type = #{identityType}
  AND identifier = #{identifier}
